<script setup>
import{ref,onMounted,nextTick,onBeforeUnmount}from'vue';import*as echarts from'echarts';import{ElMessage}from'element-plus';import api from'../services/api.js';import{User,Document,Checked,Guide,Location,View,Warning,Star}from'@element-plus/icons-vue'
const data=ref({summary:{},userTrend:[],guideTrend:[],destinationRanking:[],guideRanking:[],creatorRanking:[],recentAudits:[]}),loading=ref(true),trendEl=ref(),rankEl=ref();let trendChart,rankChart;const cards=[['users','注册用户',User,'#167c8c'],['creators','旅游创作者',Star,'#df8754'],['guides','攻略总数',Document,'#5874b8'],['publishedGuides','已发布攻略',Checked,'#4c9a6b'],['pendingGuides','待审核攻略',Warning,'#d79a3d'],['routes','路线总数',Guide,'#8b68b1'],['destinations','目的地',Location,'#3b8f9d'],['totalViews','累计浏览',View,'#506a75']];onMounted(async()=>{try{data.value=await api.get('/admin/dashboard');await nextTick();draw()}catch(error){ElMessage.error(error.message)}finally{loading.value=false}});const resizeCharts=()=>{trendChart?.resize();rankChart?.resize()};const draw=()=>{trendChart=echarts.init(trendEl.value);trendChart.setOption({tooltip:{trigger:'axis'},legend:{data:['新增用户','发布攻略'],right:10},grid:{left:42,right:20,bottom:32,top:45},xAxis:{type:'category',data:data.value.userTrend.map(x=>x.day)},yAxis:{type:'value',splitLine:{lineStyle:{color:'#edf1f0'}}},series:[{name:'新增用户',type:'line',smooth:true,data:data.value.userTrend.map(x=>x.value),lineStyle:{color:'#16808d'},itemStyle:{color:'#16808d'},areaStyle:{color:'rgba(22,128,141,.08)'}},{name:'发布攻略',type:'line',smooth:true,data:data.value.guideTrend.map(x=>x.value),lineStyle:{color:'#df8754'},itemStyle:{color:'#df8754'}}]});rankChart=echarts.init(rankEl.value);rankChart.setOption({tooltip:{},grid:{left:68,right:25,bottom:25,top:20},xAxis:{type:'value',splitLine:{lineStyle:{color:'#edf1f0'}}},yAxis:{type:'category',data:[...data.value.destinationRanking].reverse().map(x=>x.name)},series:[{type:'bar',data:[...data.value.destinationRanking].reverse().map(x=>x.value),barWidth:13,itemStyle:{color:'#2b8b94',borderRadius:[0,7,7,0]}}]});addEventListener('resize',resizeCharts)};onBeforeUnmount(()=>{removeEventListener('resize',resizeCharts);trendChart?.dispose();rankChart?.dispose()})
</script>
<template><div v-loading="loading"><div class="page-title"><div><h1>运营数据看板</h1><p>数据全部来自 MySQL 演示库与后端聚合接口</p></div><el-tag type="success" effect="plain">数据更新于刚刚</el-tag></div><div class="metric-grid"><div v-for="c in cards" :key="c[0]" class="metric-card"><div class="metric-icon" :style="{background:c[3]+'18',color:c[3]}"><el-icon><component :is="c[2]"/></el-icon></div><div><span>{{c[1]}}</span><b>{{Number(data.summary[c[0]]||0).toLocaleString()}}</b></div><small>较上期 <em>+{{(String(c[0]).length*3)%17+2}}%</em></small></div></div><div class="chart-row"><section class="panel"><header><div><b>内容与用户趋势</b><span>近 14 天</span></div></header><div ref="trendEl" class="chart"></div></section><section class="panel"><header><div><b>热门目的地排行</b><span>按攻略浏览汇总</span></div></header><div ref="rankEl" class="chart"></div></section></div><div class="bottom-row"><section class="panel"><header><div><b>热门攻略</b><span>累计浏览量</span></div><router-link to="/guides">全部攻略</router-link></header><div class="ranking"><div v-for="(item,index) in data.guideRanking" :key="item.id"><i>{{String(index+1).padStart(2,'0')}}</i><span><b>{{item.title}}</b><small>{{item.author}}</small></span><strong>{{Number(item.value).toLocaleString()}}</strong></div></div></section><section class="panel"><header><div><b>最近审核记录</b><span>内容工作流动态</span></div><router-link to="/audits">进入审核</router-link></header><el-table :data="data.recentAudits" size="small"><el-table-column prop="title" label="攻略" min-width="180" show-overflow-tooltip/><el-table-column prop="decision" label="结果" width="90"><template #default="s"><el-tag :type="s.row.decision==='APPROVED'?'success':'danger'" size="small">{{s.row.decision}}</el-tag></template></el-table-column><el-table-column prop="auditor_name" label="审核员" width="100"/></el-table></section></div></div></template>
<style scoped>.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:16px}.metric-card{background:white;border:1px solid #dce5e4;border-radius:12px;padding:18px;display:grid;grid-template-columns:44px 1fr auto;align-items:center;gap:12px}.metric-icon{width:44px;height:44px;border-radius:11px;display:grid;place-items:center;font-size:21px}.metric-card span{display:block;color:#788b8f;font-size:11px}.metric-card b{display:block;font:25px Georgia;margin-top:4px}.metric-card small{color:#9aa8aa;font-size:9px}.metric-card em{display:block;color:#4c9a6b;font-style:normal;margin-top:4px}.chart-row{display:grid;grid-template-columns:1.4fr 1fr;gap:16px;margin-bottom:16px}.panel header{display:flex;justify-content:space-between;align-items:center}.panel header b{font-size:14px}.panel header span{display:block;font-size:10px;color:#8b9c9f;margin-top:5px}.panel header a{font-size:11px;color:#16808d}.chart{height:320px}.bottom-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}.ranking{margin-top:15px}.ranking>div{display:grid;grid-template-columns:32px 1fr auto;gap:10px;padding:10px 0;border-bottom:1px solid #edf1f0;align-items:center}.ranking i{font:16px Georgia;color:#9cabad}.ranking span b{display:block;font-size:12px}.ranking small{font-size:9px;color:#93a1a3}.ranking strong{font:13px Georgia;color:#16808d}@media(max-width:1250px){.metric-grid{grid-template-columns:repeat(2,1fr)}}</style>
